44	/**
45	 * @brief Run a C-API entry-point body inside an exception barrier.
46	 *
47	 * gh#74 (v2.3.13): every `extern "C"` function in this translation
48	 * unit MUST guarantee that no C++ exception escapes back into the
49	 * caller (per `docs/architecture-cpp.md`'s "exceptions do not cross
50	 * .so boundaries" rule). Wraps the body in try/catch and maps the
51	 * three exception families we've actually seen to documented error
52	 * codes:
53	 *
54	 *   - `std::filesystem::filesystem_error` → `ENTROPIC_ERROR_IO`
55	 *   - `nlohmann::json::exception`         → `ENTROPIC_ERROR_INVALID_CONFIG`
56	 *   - any other `std::exception`          → `ENTROPIC_ERROR_INTERNAL`
57	 *
58	 * The handle's `last_error` is populated with `what()` when handle is
59	 * non-null so consumers can read it via `entropic_last_error()`. Logs
60	 * at error level on every catch so the operator sees the exception
61	 * type alongside the C error code that surfaced.
62	 *
63	 * Rolled out incrementally — v2.3.13 covers the three configure
64	 * entry points that gh#74 reported as visibly leaking. Other extern-C
65	 * functions can wrap their bodies the same way as needed.
66	 *
67	 * @param handle Engine handle for `last_error` write (may be NULL).
68	 * @param fn Body returning the natural success / error code.
69	 * @return `fn()`'s return value on no exception; mapped error code
70	 *         otherwise.
71	 * @utility
72	 * @version 2.3.13
73	 */
74	template <typename Fn>
75	static entropic_error_t c_api_try(entropic_handle_t handle, Fn&& fn) {
76	    entropic_error_t rc = ENTROPIC_ERROR_INTERNAL;
77	    try {
78	        rc = fn();
79	    } catch (const std::filesystem::filesystem_error& e) {
80	        if (handle) { handle->last_error = e.what(); }
81	        s_log->error("c_api filesystem_error: {}", e.what());
82	        rc = ENTROPIC_ERROR_IO;
83	    } catch (const nlohmann::json::exception& e) {
84	        if (handle) { handle->last_error = e.what(); }
85	        s_log->error("c_api json::exception: {}", e.what());
86	        rc = ENTROPIC_ERROR_INVALID_CONFIG;
87	    } catch (const std::exception& e) {
88	        if (handle) { handle->last_error = e.what(); }
89	        s_log->error("c_api std::exception: {}", e.what());
90	        rc = ENTROPIC_ERROR_INTERNAL;
91	    }
92	    return rc;
93	}
