95	/**
96	 * @brief Allocate a C string copy via the engine allocator.
97	 *
98	 * Uses entropic_alloc so the caller can free with entropic_free().
99	 * Returns NULL on allocation failure (OOM).
100	 *
101	 * @param src Source string (null-terminated).
102	 * @return Heap-allocated copy, or NULL on OOM.
103	 * @utility
104	 * @version 2.0.1
105	 */
106	static char* alloc_cstr(const char* src) {
107	    if (!src) { return nullptr; }
108	    size_t len = std::strlen(src) + 1;
109	    auto* dst = static_cast<char*>(entropic_alloc(len));
110	    if (dst) { std::memcpy(dst, src, len); }
111	    return dst;
112	}
