127	// gh#58 follow-up (v2.2.6): per-handle last_error. Pre-v2.2.6 the
128	// public API in src/types/error.cpp ignored the handle parameter and
129	// returned a single thread-local buffer, so every handle->last_error
130	// assignment in the facade was unreadable from the consumer side.
131	// Thread-local cache here means the returned const char* stays valid
132	// until the *same* thread calls entropic_last_error again — matching
133	// the documented v1.8.0 contract.
134	static thread_local std::string s_last_error_cache;
135	static thread_local char s_pre_create_error[512] = "";
136	
137	/**
138	 * @brief Read the per-handle last_error under api_mutex.
139	 *
140	 * Pre-v2.2.6 the public symbol lived in src/types/error.cpp and
141	 * ignored its handle parameter (v1.8.0 TODO never done). Moved here
142	 * because the private engine_handle struct is only visible in the
143	 * facade. Returns a thread-local cache copy so the pointer stays
144	 * valid until the same thread reads again — matches the v1.8.0
145	 * contract documented in include/entropic/types/error.h.
146	 *
147	 * @utility
148	 * @version 2.2.6
149	 */
150	extern "C" const char* entropic_last_error(entropic_handle_t handle) {
151	    if (!handle) { return s_pre_create_error; }
152	    entropic::HandleApiLock lock(handle);  // gh#59 v2.3.1: mutex + log scope
153	    s_last_error_cache = handle->last_error;
154	    return s_last_error_cache.c_str();
155	}
