214	    entropic_handle_t h, const char* tier_name)
215	{
216	    auto* backend = h->orchestrator->get_backend(tier_name);
217	    if (!backend) {
218	        throw std::runtime_error(
219	            "no backend for tier: " + std::string(tier_name));
