327	/**
328	 * @brief Filter tool definitions by allowed list.
329	 *
330	 * @param all_tools Parsed JSON array of all tool definitions.
331	 * @param allowed Allowed tool names (empty = no filter).
332	 * @return JSON strings of matching tools.
333	 * @utility
334	 * @version 2.0.4
335	 */
336	static std::vector<std::string> filter_tools(
337	    const nlohmann::json& all_tools,
338	    const std::vector<std::string>& allowed) {
339	    std::vector<std::string> result;
340	    for (const auto& tool : all_tools) {
341	        std::string name = tool.value("name", "");
342	        bool pass = allowed.empty()
343	            || std::find(allowed.begin(), allowed.end(), name)
344	               != allowed.end();
345	        if (pass) { result.push_back(tool.dump()); }
346	    }
347	    return result;
348	}
