350	/**
351	 * @brief Build formatted tool prompt for a tier.
352	 *
353	 * gh#87 (v2.7.0): returns the per-tier-filtered tool defs as a structured
354	 * MCP JSON array (`[{name, description, inputSchema}, ...]`), NOT an
355	 * adapter-formatted prompt string. The defs flow into `params.tools` and
356	 * common_chat renders them in the model's native format — so no adapter
357	 * `format_tools` and no system-message string injection. The field's
358	 * contract ("tool definitions for tier") is unchanged; only the payload
359	 * shape evolved from formatted-prompt to structured-JSON.
360	 *
361	 * @param tier Tier name.
362	 * @param result Output: heap-allocated JSON-array string. Caller frees.
363	 * @param user_data Engine handle.
364	 * @return 0 on success, non-zero if no tools available.
365	 * @callback
366	 * @version 2.7.0
367	 */
368	static int facade_get_tool_prompt(const char* tier, char** result,
369	                                  void* user_data) {
370	    auto* h = static_cast<entropic_engine*>(user_data);
371	    *result = nullptr;
372	    if (!h || !h->server_manager) { return 1; }
373	
374	    std::string tier_name = tier ? tier : "";
375	    auto all_json = h->server_manager->list_tools();
376	    auto all_tools = nlohmann::json::parse(all_json, nullptr, false);
377	    auto allowed = resolve_allowed_tools(h, tier_name);
378	    auto tool_jsons = filter_tools(all_tools, allowed);
379	    if (!all_tools.is_array() || all_tools.empty() || tool_jsons.empty()) {
380	        return 1;
381	    }
382	
383	    nlohmann::json arr = nlohmann::json::array();
384	    for (const auto& tj : tool_jsons) {
385	        auto obj = nlohmann::json::parse(tj, nullptr, false);
386	        if (!obj.is_discarded()) { arr.push_back(std::move(obj)); }
387	    }
388	    *result = strdup(arr.dump().c_str());
389	    return 0;
390	}
