509	/**
510	 * @brief Register per-tier ChildContextInfo with the engine.
511	 *
512	 * Extracted from configure_common to keep that function under the
513	 * 50-SLOC quality gate. Iterates the configured tiers, resolves each
514	 * identity file, and registers the assembled context with the engine.
515	 *
516	 * @param h Engine handle (engine must be constructed).
517	 * @param data_dir Resolved data directory for identity files.
518	 * @param shared_prefix Prefix assembled from constitution + app context.
519	 * @utility
520	 * @version 2.9.20
521	 */
522	static void populate_tier_info(entropic_handle_t h,
523	                               const std::filesystem::path& data_dir,
524	                               const std::string& shared_prefix) {
525	    for (const auto& [name, tier] : h->config.models.tiers) {
526	        entropic::ChildContextInfo info;
527	        info.valid = true;
528	        auto parsed = entropic::prompts::resolve_tier_identity_full(
529	            tier, name, data_dir);
530	        info.system_prompt = shared_prefix + parsed.body;
531	        info.explicit_completion = parsed.frontmatter.explicit_completion
532	            .value_or(!tier.auto_chain.has_value());
533	        // E6 (2.0.6-rc18): propagate per-identity caps from frontmatter
534	        // so AgentEngine::tri_get_tier_param surfaces them to the loop
535	        // and tool executor. -1 = "use global loop_config default".
536	        info.max_iterations_override =
537	            parsed.frontmatter.max_iterations;
538	        info.max_tool_calls_per_turn_override =
539	            parsed.frontmatter.max_tool_calls_per_turn;
540	        info.max_consecutive_empty_turns_override =
541	            parsed.frontmatter.max_consecutive_empty_turns;
542	        info.allowed_tools = resolve_allowed_tools(h, name);  // gh#121
543	        h->engine->set_tier_info(name, info);
544	    }
545	}
