652	/**
653	 * @brief StorageInterface bridge: load_delegation_with_messages.
654	 *
655	 * Resolves delegation id → child_conversation_id → conversation messages,
656	 * then returns the composed JSON with `target_tier` and `messages` at
657	 * the top level. Used by `entropic.resume_delegation` (gh#32, v2.1.6).
658	 *
659	 * @callback
660	 * @version 2.1.6
661	 */
662	static bool si_load_delegation_with_messages(
663	        const char* delegation_id, std::string& result_json,
664	        void* user_data) {
665	    auto* sb = static_cast<entropic::SqliteStorageBackend*>(user_data);
666	    bool ok = sb != nullptr && delegation_id != nullptr;
667	    std::string del_json;
668	    nlohmann::json del, conv;
669	    std::string child_id, target, conv_json;
670	    if (ok) {
671	        ok = sb->get_delegation_by_id(delegation_id, del_json);
672	    }
673	    if (ok) {
674	        del = nlohmann::json::parse(del_json, nullptr, false);
675	        ok = del.is_object();
676	    }
677	    if (ok) {
678	        child_id = del.value("child_conversation_id", std::string{});
679	        target = del.value("target_tier", std::string{});
680	        ok = !child_id.empty() && !target.empty()
681	             && sb->load_conversation(child_id, conv_json);
682	    }
683	    if (ok) {
684	        conv = nlohmann::json::parse(conv_json, nullptr, false);
685	        ok = conv.is_object();
686	    }
687	    if (ok) {
688	        conv["target_tier"] = target;
689	        conv["delegation_id"] = del.value("id", std::string{});
690	        result_json = conv.dump();
691	    }
692	    return ok;
693	}
