746	/**
747	 * @brief Collect valid delegation targets from handoff_rules.
748	 *
749	 * Only tiers that appear as TARGETS in handoff_rules are included.
750	 * Sources are excluded — a tier should not appear in its own
751	 * delegate enum (self-delegation creates a worktree cycle for no
752	 * purpose and confuses small models).
753	 *
754	 * When handoff_rules is empty, falls back to all configured tiers
755	 * except the default tier (preserves delegation for simple configs
756	 * that define multiple tiers without explicit routing).
757	 *
758	 * @param config Parsed engine config.
759	 * @return Deduplicated tier names for delegate/pipeline schemas.
760	 * @utility
761	 * @version 2.0.6
762	 */
763	static std::vector<std::string> collect_delegatable_tiers(
764	    const entropic::ParsedConfig& config) {
765	    std::unordered_set<std::string> targets;
766	    for (const auto& [source, dests] : config.routing.handoff_rules) {
767	        for (const auto& t : dests) { targets.insert(t); }
768	    }
769	    if (targets.empty()) {
770	        for (const auto& [name, tier] : config.models.tiers) {
771	            if (name != config.models.default_tier) {
772	                targets.insert(name);
773	            }
774	        }
775	    }
776	    return {targets.begin(), targets.end()};
777	}
