829	/**
830	 * @brief Thread frontmatter sampler optionals into a tier config.
831	 *
832	 * gh#82/gh#85: each knob copies only when the frontmatter set it, so
833	 * the orchestrator's per-tier resolution can apply it as the tier
834	 * baseline. Extracted from apply_identity_frontmatter to keep that
835	 * function under the cognitive-complexity gate.
836	 *
837	 * @param tc Tier config (mutated).
838	 * @param fm Parsed identity frontmatter.
839	 * @utility
840	 * @version 2.7.4
841	 */
842	static void thread_frontmatter_sampler(
843	    entropic::TierConfig& tc,
844	    const entropic::prompts::IdentityFrontmatter& fm) {
845	    // gh#95 (v2.7.4): thread the identity `grammar:` key so the orchestrator's
846	    // resolve_grammar_key() finds it and constrains the tier's generation.
847	    // Without this the field is parsed but dropped here — registers OK, never
848	    // enforces (same class as the gh#82/85/94 sampler-threading gaps).
849	    if (fm.grammar.has_value()) {
850	        tc.grammar = std::filesystem::path(*fm.grammar);
851	    }
852	    if (fm.temperature.has_value()) { tc.temperature = *fm.temperature; }
853	    if (fm.max_output_tokens.has_value()) {
854	        tc.max_output_tokens = *fm.max_output_tokens;
855	    }
856	    if (fm.top_p.has_value()) { tc.top_p = *fm.top_p; }
857	    if (fm.top_k.has_value()) { tc.top_k = *fm.top_k; }
858	    if (fm.min_p.has_value()) { tc.min_p = *fm.min_p; }
859	    if (fm.presence_penalty.has_value()) {
860	        tc.presence_penalty = *fm.presence_penalty;
861	    }
862	    if (fm.frequency_penalty.has_value()) {
863	        tc.frequency_penalty = *fm.frequency_penalty;
864	    }
865	    // gh#86 (v2.5.4): repeat_penalty + enable_thinking.
866	    if (fm.repeat_penalty.has_value()) { tc.repeat_penalty = *fm.repeat_penalty; }
867	    if (fm.enable_thinking.has_value()) {
868	        tc.enable_thinking = *fm.enable_thinking;
869	    }
870	}
