872	/**
873	 * @brief Apply a parsed identity's frontmatter to the engine handle.
874	 * @param h Engine handle.
875	 * @param name Tier name.
876	 * @param fm Parsed frontmatter.
877	 * @internal
878	 * @version 2.7.3
879	 */
880	static void apply_identity_frontmatter(
881	    entropic_handle_t h,
882	    const std::string& name,
883	    const entropic::prompts::IdentityFrontmatter& fm) {
884	    if (fm.allowed_tools.has_value()) {
885	        h->tier_allowed_tools[name] = *fm.allowed_tools;
886	    }
887	    if (!fm.validation_rules.empty()) {
888	        h->tier_validation_rules[name] = fm.validation_rules;
889	    }
890	    if (fm.relay_single_delegate) {
891	        h->engine->set_relay_single_delegate(name);
892	    }
893	    // gh#94 (v2.7.3): per-tier frontmatter SAMPLERS are threaded earlier, in
894	    // thread_frontmatter_samplers() BEFORE init_orchestrator, so they land in
895	    // the orchestrator's by-value config snapshot. Threading them HERE (after
896	    // the snapshot) was the gh#94 ordering bug — the values reached h->config
897	    // but never the orchestrator's frozen copy, so tiers ran defaults.
898	}
