933	/**
934	 * @brief Thread per-tier frontmatter SAMPLERS into config pre-orchestrator.
935	 *
936	 * gh#94 (v2.7.3): the orchestrator snapshots `h->config` BY VALUE in
937	 * init_orchestrator() (`config_ = config`). The engine-bound frontmatter
938	 * wiring (cache_tier_allowed_tools → apply_identity_frontmatter) necessarily
939	 * runs LATER, after the engine exists. Threading sampler knobs there left them
940	 * in `h->config` but never in the orchestrator's frozen copy, so every tier
941	 * silently ran GenerationParams defaults regardless of frontmatter. This pass
942	 * threads ONLY the dependency-free sampler knobs into each tier BEFORE
943	 * init_orchestrator, so the snapshot carries them. The engine-dependent
944	 * wiring (allowed_tools, relay_single_delegate, tool_executor) stays in
945	 * wire_prompts_and_persistence.
946	 *
947	 * @param h Engine handle (config tiers mutated in place).
948	 * @param data_dir Bundled data directory (identity file resolution).
949	 * @internal
950	 * @version 2.7.3
951	 */
952	static void thread_frontmatter_samplers(
953	    entropic_handle_t h,
954	    const std::filesystem::path& data_dir) {
955	    for (auto& [name, tier] : h->config.models.tiers) {
956	        std::filesystem::path id_path;
957	        if (tier.identity.has_value()) {
958	            id_path = tier.identity.value();
959	        } else if (!tier.identity_disabled) {
960	            id_path = data_dir / "prompts" / ("identity_" + name + ".md");
961	        }
962	        if (id_path.empty() || !std::filesystem::exists(id_path)) {
963	            continue;
964	        }
965	        entropic::prompts::ParsedIdentity id;
966	        if (entropic::prompts::load_identity(id_path, id).empty()) {
967	            thread_frontmatter_sampler(tier, id.frontmatter);
968	        }
969	    }
970	}
