978	/**
979	 * @brief C-safe accessor for ToolExecutor's history (P1-11).
980	 *
981	 * Extracted to satisfy the 3-return complexity gate.
982	 *
983	 * @param count Max entries to serialize.
984	 * @param ud ToolExecutor pointer.
985	 * @return malloc'd JSON string, or nullptr when empty/unset.
986	 * @utility
987	 * @version 2.0.6-rc16
988	 */
989	static char* tool_history_json_thunk(size_t count, void* ud) {
990	    auto* exec = static_cast<entropic::ToolExecutor*>(ud);
991	    if (exec == nullptr) { return nullptr; }
992	    auto s = exec->tool_history().to_json(count);
993	    if (s.empty() || s == "[]") { return nullptr; }
994	    auto* out = static_cast<char*>(std::malloc(s.size() + 1));
995	    if (out != nullptr) {
996	        std::memcpy(out, s.data(), s.size());
997	        out[s.size()] = '\0';
998	    }
999	    return out;
1000	}
