1032	/**
1033	 * @brief Return the validator's last verdict as JSON for ON_COMPLETE.
1034	 *
1035	 * Shape: {ran, verdict, violations[], revisions_applied}. Verdict
1036	 * is a string from {passed, revised, rejected_reverted_length,
1037	 * rejected_max_revisions}. Returns malloc'd buffer; engine frees.
1038	 * (E3, 2.0.6-rc17)
1039	 *
1040	 * @param ud entropic_engine handle.
1041	 * @return JSON string or NULL if validator not configured.
1042	 * @callback
1043	 * @version 2.1.5
1044	 */
1045	static char* sp_get_validation(void* ud) {
1046	    auto* h = static_cast<entropic_engine*>(ud);
1047	    if (h == nullptr || h->validator == nullptr) { return nullptr; }
1048	    auto r = h->validator->last_result();
1049	    nlohmann::json v;
1050	    v["ran"] = true;
1051	    switch (r.verdict) {
1052	    case entropic::ValidationVerdict::passed:
1053	        v["verdict"] = "passed"; break;
1054	    case entropic::ValidationVerdict::revised:
1055	        v["verdict"] = "revised"; break;
1056	    case entropic::ValidationVerdict::rejected_reverted_length:
1057	        v["verdict"] = "rejected_reverted_length"; break;
1058	    case entropic::ValidationVerdict::rejected_max_revisions:
1059	        v["verdict"] = "rejected_max_revisions"; break;
1060	    case entropic::ValidationVerdict::skipped:
1061	        v["verdict"] = "skipped"; break;
1062	    case entropic::ValidationVerdict::paused_pending_consumer:
1063	        v["verdict"] = "paused_pending_consumer"; break;
1064	    case entropic::ValidationVerdict::passed_consumer_override:
1065	        v["verdict"] = "passed_consumer_override"; break;
1066	    }
1067	    v["revisions_applied"] = r.revision_count;
1068	    // gh#30 (v2.1.5): structured fields the consumer needs to render
1069	    // a "retry / override / re-prompt" UI without parsing free-form
1070	    // reason strings.
1071	    v["attempt_n"] = r.attempt_n;
1072	    nlohmann::json violations = nlohmann::json::array();
1073	    for (const auto& vi : r.final_critique.violations) {
1074	        violations.push_back({
1075	            {"rule", vi.rule},
1076	            {"rule_id", vi.rule},        // alias for gh#30 schema
1077	            {"rule_text", vi.rule},      // alias for gh#30 schema
1078	            {"excerpt", vi.excerpt},
1079	            {"quote", vi.excerpt},       // alias matching gh#30 "evidence.quote"
1080	            {"explanation", vi.explanation},
1081	            {"severity", "error"},       // gh#30: hard rejection only today
1082	        });
1083	    }
1084	    v["violations"] = violations;
1085	    return strdup(v.dump().c_str());
1086	}
