1088	/**
1089	 * @brief Wire hook dispatch and attach the constitutional validator.
1090	 *
1091	 * Bridges the handle's HookRegistry to the engine's HookInterface
1092	 * (function-pointer indirection required by the .so boundary). If
1093	 * constitutional validation is enabled and constitution text was
1094	 * loaded, constructs and attaches the validator as a POST_GENERATE
1095	 * hook.
1096	 *
1097	 * @param h Engine handle with engine constructed.
1098	 * @param iface Inference interface (passed to validator for critique generation).
1099	 * @param constitution_text Constitution text (may be empty).
1100	 * @internal
1101	 * @version 2.0.6-rc19
1102	 */
1103	static void wire_hooks_and_validator(
1104	    entropic_handle_t h,
1105	    entropic::InferenceInterface& iface,
1106	    const std::string& constitution_text) {
1107	    entropic::HookInterface hook_iface;
1108	    hook_iface.registry = &h->hook_registry;
1109	    hook_iface.fire_pre = [](void* reg, entropic_hook_point_t pt,
1110	        const char* json, char** out) -> int {
1111	        return static_cast<entropic::HookRegistry*>(reg)
1112	            ->fire_pre(pt, json, out);
1113	    };
1114	    hook_iface.fire_post = [](void* reg, entropic_hook_point_t pt,
1115	        const char* json, char** out) {
1116	        static_cast<entropic::HookRegistry*>(reg)
1117	            ->fire_post(pt, json, out);
1118	    };
1119	    hook_iface.fire_info = [](void* reg, entropic_hook_point_t pt,
1120	        const char* json) {
1121	        static_cast<entropic::HookRegistry*>(reg)->fire_info(pt, json);
1122	    };
1123	    h->engine->set_hooks(hook_iface);
1124	    // E9 (2.0.6-rc19): forward the same hook dispatch to the tool
1125	    // executor so PRE_TOOL_CALL / POST_TOOL_CALL actually fire.
1126	    // Prior wiring only touched the engine; tool_executor_ held a
1127	    // null HookInterface and silently skipped all tool hooks.
1128	    if (h->tool_executor) {
1129	        h->tool_executor->set_hooks(hook_iface);
1130	    }
1131	
1132	    if (h->config.constitutional_validation.enabled
