1162	/**
1163	 * @brief Build the assembled system prompt the engine would send for
1164	 *        a given tier (constitution + app_context + identity body +
1165	 *        tool defs). Returns "" on any failure.
1166	 *
1167	 * Demo ask #3 (v2.1.0). Static parts only — does NOT include the
1168	 * per-turn iteration / validation reminders, since those are
1169	 * runtime-dependent. Runtime augmentations live in
1170	 * ResponseGenerator::inject_engine_state_reminder.
1171	 *
1172	 * @utility
1173	 * @version 2.7.0
1174	 */
1175	static std::string build_assembled_prompt_for_tier(
1176	    entropic_engine* h, const std::string& tier_name) {
1177	    auto data_dir = entropic::config::resolve_data_dir(h->config);
1178	    std::string constitution, app_ctx;
1179	    entropic::prompts::load_constitution(
1180	        h->config.constitution, h->config.constitution_disabled,
1181	        data_dir, constitution);
1182	    entropic::prompts::load_app_context(
1183	        h->config.app_context, h->config.app_context_disabled,
1184	        data_dir, app_ctx);
1185	    std::string identity_body;
1186	    auto it = h->config.models.tiers.find(tier_name);
1187	    if (it != h->config.models.tiers.end()) {
1188	        identity_body = entropic::prompts::resolve_tier_identity(
1189	            it->second, tier_name, data_dir);
1190	    }
1191	    std::string out;
1192	    if (!constitution.empty()) { out += constitution + "\n\n"; }
1193	    if (!app_ctx.empty()) { out += app_ctx + "\n\n"; }
1194	    if (!identity_body.empty()) { out += identity_body; }
1195	
1196	    // gh#87 (v2.7.0): tool defs are no longer string-injected into the
1197	    // system prompt — they flow via params.tools and common_chat renders
1198	    // them in the model's native format. So the assembled system-prompt
1199	    // preview no longer includes a tool section.
1200	    return out;
1201	}
