1242	/**
1243	 * @brief State provider: get_history — conversation context snapshot.
1244	 * @callback
1245	 *
1246	 * Returns the current conversation as a JSON array of
1247	 * {role, content_preview, token_count_est} objects, suitable for
1248	 * context_inspect MCP tool and inspect --target history. (P2-16)
1249	 *
1250	 * Content previews are truncated at 200 bytes on a UTF-8 codepoint
1251	 * boundary via `entropic::facade::utf8_safe_substr` — byte-indexed truncation would
1252	 * slice multi-byte codepoints and cause `arr.dump()` below to throw
1253	 * `nlohmann::json::type_error.316` (gh#56).
1254	 *
1255	 * @param max_entries Maximum messages to return (0 = all).
1256	 * @param ud Engine handle.
1257	 * @return JSON array string (caller frees via free()).
1258	 * @version 2.2.3
1259	 */
1260	static char* sp_get_history(int max_entries, void* ud) {
1261	    auto* h = static_cast<entropic_engine*>(ud);
1262	    if (!h || !h->engine) { return strdup("[]"); }
1263	    const auto& msgs = h->engine->get_messages();
1264	    nlohmann::json arr = nlohmann::json::array();
1265	    int start = 0;
1266	    if (max_entries > 0
1267	        && static_cast<int>(msgs.size()) > max_entries) {
1268	        start = static_cast<int>(msgs.size()) - max_entries;
1269	    }
1270	    for (int i = start; i < static_cast<int>(msgs.size()); ++i) {
1271	        const auto& m = msgs[static_cast<size_t>(i)];
1272	        std::string preview = m.content.size() > 200
1273	            ? entropic::facade::utf8_safe_substr(m.content, 200) + "..."
1274	            : m.content;
1275	        arr.push_back({
1276	            {"role",             m.role},
1277	            {"content_preview",  preview},
1278	            {"token_count_est",  m.content.size() / 4u}
1279	        });
1280	    }
1281	    return strdup(arr.dump().c_str());
1282	}
