1475	/**
1476	 * @brief Build LoopConfig from parsed config.
1477	 * @param h Engine handle with config populated.
1478	 * @return Populated LoopConfig.
1479	 * @utility
1480	 * @version 2.9.6
1481	 */
1482	static entropic::LoopConfig build_loop_config(entropic_handle_t h) {
1483	    entropic::LoopConfig lc;
1484	    // gh#110 (v2.9.6): was hardcoded true, making the agent loop always
1485	    // stream and therefore permanently out of MTP's envelope (MTP
1486	    // rejects a bound on_token callback — see mtp_envelope.h).
1487	    lc.stream_output = h->config.generation.stream_output;
1488	    lc.speculative_enabled = h->config.inference.speculative.enabled;
1489	    lc.auto_approve_tools = h->config.permissions.auto_approve;
1490	    auto it = h->config.models.tiers.find(h->config.models.default_tier);
1491	    if (it != h->config.models.tiers.end()) {
1492	        lc.context_length = it->second.context_length;
1493	    }
1494	    // gh#80 (v2.5.0): map the generation.budget_mode string to the
1495	    // BudgetMode enum. Unknown values resolve to off with a warning.
1496	    const std::string& bm = h->config.generation.budget_mode;
1497	    if (bm == "tokens") {
1498	        lc.budget_mode = entropic::BudgetMode::tokens;
1499	    } else if (bm == "wall_clock") {
1500	        lc.budget_mode = entropic::BudgetMode::wall_clock;
1501	    } else {
1502	        if (bm != "off") {
1503	            s_log->warn("Unknown generation.budget_mode '{}' — "
1504	                        "treating as 'off'", bm);
1505	        }
1506	        lc.budget_mode = entropic::BudgetMode::off;
1507	    }
1508	    lc.budget_limit = h->config.generation.budget_limit;
1509	    // A non-positive limit can't gate anything — disable to avoid a
1510	    // pathological "exhausted at zero" loop.
1511	    if (lc.budget_limit <= 0) {
1512	        lc.budget_mode = entropic::BudgetMode::off;
1513	    }
1514	    return lc;
1515	}
