1614	static void init_engine_and_interfaces(
1615	    entropic_handle_t h, const std::filesystem::path& data_dir) {
1616	    h->mcp_auth = std::make_unique<entropic::MCPAuthorizationManager>();
1617	    h->identity_manager = std::make_unique<entropic::IdentityManager>(
1618	        entropic::IdentityManagerConfig{});
1619	    // P1-7: route identity changes to prompt-cache invalidation.
1620	    h->identity_manager->set_cache_invalidator(
1621	        [](void* ud) {
1622	            auto* orch = static_cast<entropic::ModelOrchestrator*>(ud);
1623	            if (orch) { orch->clear_all_prompt_caches(); }
1624	        }, h->orchestrator.get());
1625	    init_mcp_servers(h, data_dir);
1626	
1627	    // gh#58 follow-up (v2.2.6): per-handle InterfaceContext. Pre-v2.2.6
1628	    // build_orchestrator_interface stored the context in a process-
1629	    // global static, so a second configure freed the first handle's
1630	    // context and h1.run() segfaulted on a use-after-free.
1631	    h->inference_iface = entropic::build_orchestrator_interface(
1632	        h->orchestrator.get(), h->config.models.default_tier,
1633	        &h->inference_iface_ctx);
