1637	    h->engine = std::make_unique<entropic::AgentEngine>(
1638	        h->inference_iface, lc, h->config.compaction);
1639	    // gh#76 (v2.3.27): wire the compactor registry now that the engine
1640	    // owns the CompactionManager that backs the default-compactor
1641	    // fallback. Pre-v2.3.27 the field was declared but never
1642	    // constructed, so every `entropic_register_compactor` /
1643	    // `entropic_compact` call returned INVALID_STATE.
1644	    h->compactor_registry =
1645	        std::make_unique<entropic::CompactorRegistry>(
1646	            h->engine->compaction_manager());
1647	    rewire_observers(h);  // gh#40 + fallout (v2.1.10)
1648	    wire_external_interrupt(h);  // P1-10
1649	    wire_tool_executor(h);
