 *
 * Extracted from configure_common to keep that function under the
 * 50-SLOC quality gate.  On first interrupt(), the lambda calls
 * ServerManager::interrupt_external_tools() which trips the cancel flag
 * in every StdioTransport so in-flight reads return within ~100ms.
 *
 * @param h Engine handle with engine and server_manager constructed.
 * @utility
 * @version 2.0.6-rc16
 */
static void wire_external_interrupt(entropic_handle_t h) {
    h->engine->set_external_interrupt(
        [](void* ud) {
            auto* sm = static_cast<entropic::ServerManager*>(ud);
            if (sm) { sm->interrupt_external_tools(); }
        }, h->server_manager.get());
}

/**
 * @brief Propagate any pre-configure stream observer to the new engine.
 *
 * Handles the edge case where a caller registers a stream observer
 * before entropic_configure() — the handle stores it on arrival, and
 * this helper re-binds it when the AgentEngine is constructed so
 * observers never miss tokens on a late-bound engine. (P0-1)
 *
 * @param h Engine handle with engine just constructed.
 * @utility
 * @version 2.0.6-rc16
 */
static void rewire_stream_observer(entropic_handle_t h) {
    if (h->stream_observer != nullptr && h->engine) {
        h->engine->set_stream_observer(
            h->stream_observer, h->stream_observer_data);
    }
}

/**
 * @brief Propagate any pre-configure queue observer to the new engine.
 *
 * Sibling of rewire_stream_observer for the mid-gen queue
 * consumption callback (gh#40, v2.1.10). Re-binds the handle-stored
 * observer when the AgentEngine is constructed so observers never
 * miss queue-consumption events on a late-bound engine.
 *
 * @param h Engine handle with engine just constructed.
 * @utility
 * @version 2.1.10
 */
static void rewire_queue_observer(entropic_handle_t h) {
    if (h->queue_observer != nullptr && h->engine) {
        h->engine->set_queue_observer(
            h->queue_observer, h->queue_observer_data);
    }
}

/**
 * @brief Propagate any pre-configure state observer to the new engine.
 *
 * gh#40 fallout (v2.1.10): pre-existing behavior wired the observer
 * via `engine->set_callbacks()`, which is wiped by run_streaming.
 * Re-bind through the persistent slot so pre-configure registrations
 * survive engine construction AND streaming runs.
 *
 * @param h Engine handle with engine just constructed.
 * @utility
 * @version 2.1.10
 */
static void rewire_state_observer(entropic_handle_t h) {
    if (h->state_observer != nullptr && h->engine) {
        h->engine->set_state_observer(
            h->state_observer, h->state_observer_data);
    }
}

/**
 * @brief Propagate pre-configure critique callbacks to a newly-
 *        constructed ConstitutionalValidator (gh#50, v2.1.12).
 *
 * Same pattern as rewire_state_observer: the handle owns the
 * authoritative slot; configure_common reconstructs the validator
 * each call, so the rewire helper re-applies the consumer's
 * registered callbacks after every (re)construction.
 *
 * @param h Engine handle with validator just constructed (or NULL).
 * @utility
 * @version 2.1.12
 */
static void rewire_critique_callbacks(entropic_handle_t h) {
    if ((h->critique_start_cb != nullptr || h->critique_end_cb != nullptr)
            && h->validator) {
        h->validator->set_critique_callbacks(
            h->critique_start_cb,
            h->critique_end_cb,
            h->critique_cb_data);
    }
}

/**
 * @brief Re-bind every pre-configure observer to the new engine.
 *
 * Aggregates the three rewire helpers so configure_common stays
 * under the SLOC ceiling. (gh#40 fallout, v2.1.10)
 *
 * @param h Engine handle with engine just constructed.
 * @utility
 * @version 2.1.12
 */
static void rewire_observers(entropic_handle_t h) {
    rewire_stream_observer(h);
    rewire_queue_observer(h);
    rewire_critique_callbacks(h);
    rewire_state_observer(h);
}

/**
 * @brief Register per-tier ChildContextInfo with the engine.
 *
 * Extracted from configure_common to keep that function under the
 * 50-SLOC quality gate. Iterates the configured tiers, resolves each
 * identity file, and registers the assembled context with the engine.
 *
 * @param h Engine handle (engine must be constructed).
 * @param data_dir Resolved data directory for identity files.
 * @param shared_prefix Prefix assembled from constitution + app context.
 * @utility
 * @version 2.9.20
 */
static void populate_tier_info(entropic_handle_t h,
                               const std::filesystem::path& data_dir,
                               const std::string& shared_prefix) {
    for (const auto& [name, tier] : h->config.models.tiers) {
        entropic::ChildContextInfo info;
        info.valid = true;
        auto parsed = entropic::prompts::resolve_tier_identity_full(
            tier, name, data_dir);
        info.system_prompt = shared_prefix + parsed.body;
        info.explicit_completion = parsed.frontmatter.explicit_completion
            .value_or(!tier.auto_chain.has_value());
        // E6 (2.0.6-rc18): propagate per-identity caps from frontmatter
        // so AgentEngine::tri_get_tier_param surfaces them to the loop
        // and tool executor. -1 = "use global loop_config default".
        info.max_iterations_override =
            parsed.frontmatter.max_iterations;
        info.max_tool_calls_per_turn_override =
            parsed.frontmatter.max_tool_calls_per_turn;
        info.max_consecutive_empty_turns_override =
            parsed.frontmatter.max_consecutive_empty_turns;
        info.allowed_tools = resolve_allowed_tools(h, name);  // gh#121
        h->engine->set_tier_info(name, info);
    }
}

