/**
 * @brief Initialize persistence: storage + session logger.
 * @param h Engine handle with config.log_dir set.
 * @internal
 * @version 2.0.1
 */
/**
 * @brief StorageInterface bridge: create_delegation trampoline.
 *
 * Translates the engine's StorageInterface callback into a call against
 * `SqliteStorageBackend::create_delegation`. gh#32 (v2.1.6) closes a
 * pre-existing wiring gap: the engine declared the interface but the
 * facade never populated it, so per-delegation storage records were
 * silently dropped. This is the bridge that finally connects them.
 *
 * @callback
 * @version 2.1.6
 */
static bool si_create_delegation(
        const char* parent_id, const char* delegating_tier,
        const char* target_tier, const char* task, int max_turns,
        std::string& delegation_id, std::string& child_conversation_id,
        void* user_data) {
    auto* sb = static_cast<entropic::SqliteStorageBackend*>(user_data);
    if (sb == nullptr) { return false; }
    return sb->create_delegation(
        parent_id ? parent_id : "",
        delegating_tier ? delegating_tier : "",
        target_tier ? target_tier : "",
        task ? task : "",
        max_turns, delegation_id, child_conversation_id);
}

/**
 * @brief StorageInterface bridge: create_conversation trampoline.
 *
 * Forwards `AgentEngine::run`'s root-conversation creation to the
 * `SqliteStorageBackend`. Pre-v2.1.12 (gh#48) the interface had no
 * `create_conversation` callback, so the root conversation row was
 * never inserted and every subsequent delegation's FK to
 * `conversations(id)` failed silently against the empty parent id.
 *
 * @callback
 * @version 2.1.12
 */
static bool si_create_conversation(
        const char* title, std::string& conversation_id,
        void* user_data) {
    auto* sb = static_cast<entropic::SqliteStorageBackend*>(user_data);
    if (sb == nullptr) { return false; }
    conversation_id = sb->create_conversation(
        title ? title : "session", std::nullopt, std::nullopt);
    return !conversation_id.empty();
}

/**
 * @brief StorageInterface bridge: complete_delegation trampoline.
 * @callback
 * @version 2.1.6
 */
static bool si_complete_delegation(
        const char* delegation_id, const char* status,
        const char* summary, void* user_data) {
    auto* sb = static_cast<entropic::SqliteStorageBackend*>(user_data);
    if (sb == nullptr || delegation_id == nullptr) { return false; }
    std::optional<std::string> sum;
    if (summary != nullptr) { sum = summary; }
    return sb->complete_delegation(delegation_id,
                                   status ? status : "completed", sum);
}

/**
 * @brief StorageInterface bridge: save_conversation trampoline.
 * @callback
 * @version 2.1.6
 */
static bool si_save_conversation(
        const char* conversation_id, const char* messages_json,
        void* user_data) {
    auto* sb = static_cast<entropic::SqliteStorageBackend*>(user_data);
    if (sb == nullptr || conversation_id == nullptr
        || messages_json == nullptr) {
        return false;
    }
    return sb->save_messages(conversation_id, messages_json);
}

/**
 * @brief StorageInterface bridge: save_snapshot trampoline.
 * @callback
 * @version 2.1.6
 */
static bool si_save_snapshot(
        const char* conversation_id, const char* messages_json,
        void* user_data) {
    auto* sb = static_cast<entropic::SqliteStorageBackend*>(user_data);
    if (sb == nullptr || conversation_id == nullptr
        || messages_json == nullptr) {
        return false;
    }
    return sb->save_snapshot(conversation_id, messages_json);
}

/**
 * @brief StorageInterface bridge: load_delegation_with_messages.
 *
 * Resolves delegation id → child_conversation_id → conversation messages,
 * then returns the composed JSON with `target_tier` and `messages` at
 * the top level. Used by `entropic.resume_delegation` (gh#32, v2.1.6).
 *
 * @callback
 * @version 2.1.6
 */
static bool si_load_delegation_with_messages(
        const char* delegation_id, std::string& result_json,
        void* user_data) {
    auto* sb = static_cast<entropic::SqliteStorageBackend*>(user_data);
    bool ok = sb != nullptr && delegation_id != nullptr;
    std::string del_json;
    nlohmann::json del, conv;
    std::string child_id, target, conv_json;
    if (ok) {
        ok = sb->get_delegation_by_id(delegation_id, del_json);
    }
    if (ok) {
        del = nlohmann::json::parse(del_json, nullptr, false);
        ok = del.is_object();
    }
    if (ok) {
        child_id = del.value("child_conversation_id", std::string{});
        target = del.value("target_tier", std::string{});
        ok = !child_id.empty() && !target.empty()
             && sb->load_conversation(child_id, conv_json);
    }
    if (ok) {
        conv = nlohmann::json::parse(conv_json, nullptr, false);
        ok = conv.is_object();
    }
    if (ok) {
        conv["target_tier"] = target;
        conv["delegation_id"] = del.value("id", std::string{});
        result_json = conv.dump();
    }
    return ok;
}

/**
 * @brief Build a populated StorageInterface bound to `sb`.
 *
 * gh#32 (v2.1.6): pre-2.1.6 nothing called `AgentEngine::set_storage`
 * so the engine's StorageInterface fields were all nullptr and the
 * delegation/compaction storage paths were dead code. This builder
 * closes that gap.
 *
 * @param sb Storage backend (non-owning).
 * @return StorageInterface ready to pass to `AgentEngine::set_storage`.
 * @internal
 * @version 2.1.12
 */
static entropic::StorageInterface build_storage_iface(
        entropic::SqliteStorageBackend* sb) {
    entropic::StorageInterface si{};
    si.create_conversation = si_create_conversation;
    si.create_delegation = si_create_delegation;
    si.complete_delegation = si_complete_delegation;
    si.save_conversation = si_save_conversation;
    si.save_snapshot = si_save_snapshot;
    si.load_delegation_with_messages = si_load_delegation_with_messages;
    si.user_data = sb;
    return si;
}

/**
 * @brief Initialize persistence: storage + session logger + StorageInterface.
 * @internal
 * @version 2.1.6
 */
static void init_persistence(entropic_handle_t h) {
    if (h->config.log_dir.empty()) { return; }
    auto db_path = h->config.log_dir / "entropic.db";
    h->storage = std::make_unique<entropic::SqliteStorageBackend>(db_path);
    if (h->storage->initialize()) {
        s_log->info("storage: {}", db_path.string());
    } else {
        s_log->warn("storage init failed, continuing without persistence");
        h->storage.reset();
    }
    // gh#32 (v2.1.6): wire StorageInterface into the engine so the
    // create_delegation/save_conversation paths actually persist (they
    // were dead code pre-2.1.6 because nothing populated the iface).
    if (h->storage && h->engine) {
        h->engine->set_storage(build_storage_iface(h->storage.get()));
    }
    h->session_logger = std::make_unique<entropic::SessionLogger>(
        h->config.log_dir);
}

/**
 * @brief Collect valid delegation targets from handoff_rules.
 *
 * Only tiers that appear as TARGETS in handoff_rules are included.
 * Sources are excluded — a tier should not appear in its own
 * delegate enum (self-delegation creates a worktree cycle for no
 * purpose and confuses small models).
 *
 * When handoff_rules is empty, falls back to all configured tiers
 * except the default tier (preserves delegation for simple configs
 * that define multiple tiers without explicit routing).
 *
 * @param config Parsed engine config.
 * @return Deduplicated tier names for delegate/pipeline schemas.
 * @utility
 * @version 2.0.6
 */
static std::vector<std::string> collect_delegatable_tiers(
    const entropic::ParsedConfig& config) {
    std::unordered_set<std::string> targets;
    for (const auto& [source, dests] : config.routing.handoff_rules) {
        for (const auto& t : dests) { targets.insert(t); }
    }
    if (targets.empty()) {
        for (const auto& [name, tier] : config.models.tiers) {
            if (name != config.models.default_tier) {
                targets.insert(name);
            }
        }
    }
    return {targets.begin(), targets.end()};
}

/**
 * @brief Initialize MCP servers with resolved working directory.
 * @param h Engine handle with config loaded.
 * @param data_dir Bundled data directory path.
 * @internal
 * @version 2.0.4
 */
static void init_mcp_servers(entropic_handle_t h,
                             const std::filesystem::path& data_dir) {
    auto root = h->config.mcp.working_dir.empty()
        ? std::filesystem::current_path()
        : std::filesystem::path(h->config.mcp.working_dir);
    h->server_manager = std::make_unique<entropic::ServerManager>(
        h->config.permissions, root);
    auto tier_names = collect_delegatable_tiers(h->config);
    h->server_manager->init_builtins(
        h->config.mcp, tier_names, data_dir.string());
}

/**
 * @brief Build shared system prompt prefix (constitution + app_context).
 * @param h Engine handle with config loaded.
 * @param data_dir Bundled data directory.
 * @return Concatenated prefix string.
 * @utility
 * @version 2.0.4
 */
static std::string build_shared_prompt_prefix(
    entropic_handle_t h,
    const std::filesystem::path& data_dir) {
    std::string constitution, app_ctx;
    entropic::prompts::load_constitution(
        h->config.constitution, h->config.constitution_disabled,
        data_dir, constitution);
    entropic::prompts::load_app_context(
        h->config.app_context, h->config.app_context_disabled,
        data_dir, app_ctx);
    std::string prefix;
    if (!constitution.empty()) { prefix += constitution + "\n\n"; }
    if (!app_ctx.empty()) { prefix += app_ctx + "\n\n"; }
    return prefix;
}

/**
 * @brief Cache per-tier frontmatter fields (allowed_tools, validation_rules, relay).
 * @param h Engine handle with config + engine constructed.
 * @param data_dir Bundled data directory.
 * @internal
 * @version 2.0.11
 */
/**
 * @brief Thread frontmatter sampler optionals into a tier config.
 *
 * gh#82/gh#85: each knob copies only when the frontmatter set it, so
 * the orchestrator's per-tier resolution can apply it as the tier
 * baseline. Extracted from apply_identity_frontmatter to keep that
 * function under the cognitive-complexity gate.
 *
 * @param tc Tier config (mutated).
 * @param fm Parsed identity frontmatter.
 * @utility
 * @version 2.7.4
 */
static void thread_frontmatter_sampler(
    entropic::TierConfig& tc,
    const entropic::prompts::IdentityFrontmatter& fm) {
    // gh#95 (v2.7.4): thread the identity `grammar:` key so the orchestrator's
    // resolve_grammar_key() finds it and constrains the tier's generation.
    // Without this the field is parsed but dropped here — registers OK, never
    // enforces (same class as the gh#82/85/94 sampler-threading gaps).
    if (fm.grammar.has_value()) {
        tc.grammar = std::filesystem::path(*fm.grammar);
    }
    if (fm.temperature.has_value()) { tc.temperature = *fm.temperature; }
    if (fm.max_output_tokens.has_value()) {
        tc.max_output_tokens = *fm.max_output_tokens;
    }
    if (fm.top_p.has_value()) { tc.top_p = *fm.top_p; }
    if (fm.top_k.has_value()) { tc.top_k = *fm.top_k; }
    if (fm.min_p.has_value()) { tc.min_p = *fm.min_p; }
    if (fm.presence_penalty.has_value()) {
        tc.presence_penalty = *fm.presence_penalty;
    }
    if (fm.frequency_penalty.has_value()) {
        tc.frequency_penalty = *fm.frequency_penalty;
    }
    // gh#86 (v2.5.4): repeat_penalty + enable_thinking.
    if (fm.repeat_penalty.has_value()) { tc.repeat_penalty = *fm.repeat_penalty; }
    if (fm.enable_thinking.has_value()) {
        tc.enable_thinking = *fm.enable_thinking;
    }
}

/**
 * @brief Apply a parsed identity's frontmatter to the engine handle.
 * @param h Engine handle.
 * @param name Tier name.
 * @param fm Parsed frontmatter.
 * @internal
 * @version 2.7.3
 */
static void apply_identity_frontmatter(
    entropic_handle_t h,
    const std::string& name,
    const entropic::prompts::IdentityFrontmatter& fm) {
    if (fm.allowed_tools.has_value()) {
        h->tier_allowed_tools[name] = *fm.allowed_tools;
    }
    if (!fm.validation_rules.empty()) {
        h->tier_validation_rules[name] = fm.validation_rules;
    }
    if (fm.relay_single_delegate) {
        h->engine->set_relay_single_delegate(name);
    }
    // gh#94 (v2.7.3): per-tier frontmatter SAMPLERS are threaded earlier, in
    // thread_frontmatter_samplers() BEFORE init_orchestrator, so they land in
    // the orchestrator's by-value config snapshot. Threading them HERE (after
    // the snapshot) was the gh#94 ordering bug — the values reached h->config
    // but never the orchestrator's frozen copy, so tiers ran defaults.
}

/**
 * @brief Cache per-tier frontmatter fields from identity files.
 * @param h Engine handle with config + engine constructed.
 * @param data_dir Bundled data directory.
 * @internal
 * @version 2.5.2
 */
static void cache_tier_allowed_tools(
    entropic_handle_t h,
    const std::filesystem::path& data_dir) {
    for (const auto& [name, tier] : h->config.models.tiers) {
        std::filesystem::path id_path;
        if (tier.identity.has_value()) {
            id_path = tier.identity.value();
        } else if (!tier.identity_disabled) {
            id_path = data_dir / "prompts" / ("identity_" + name + ".md");
        }
        if (id_path.empty() || !std::filesystem::exists(id_path)) {
            continue;
        }
        entropic::prompts::ParsedIdentity id;
        if (entropic::prompts::load_identity(id_path, id).empty()) {
            apply_identity_frontmatter(h, name, id.frontmatter);
        }
    }
    // gh#83 (v2.5.2): hand the populated allowlist map to the executor
    // for dispatch-time enforcement. A pointer to the handle-owned map
    // keeps this order-independent vs wire_tool_executor.
    if (h->tool_executor) {
        h->tool_executor->set_tier_allowed_tools(&h->tier_allowed_tools);
    }
}

/**
 * @brief Thread per-tier frontmatter SAMPLERS into config pre-orchestrator.
 *
 * gh#94 (v2.7.3): the orchestrator snapshots `h->config` BY VALUE in
 * init_orchestrator() (`config_ = config`). The engine-bound frontmatter
 * wiring (cache_tier_allowed_tools → apply_identity_frontmatter) necessarily
 * runs LATER, after the engine exists. Threading sampler knobs there left them
 * in `h->config` but never in the orchestrator's frozen copy, so every tier
 * silently ran GenerationParams defaults regardless of frontmatter. This pass
 * threads ONLY the dependency-free sampler knobs into each tier BEFORE
 * init_orchestrator, so the snapshot carries them. The engine-dependent
 * wiring (allowed_tools, relay_single_delegate, tool_executor) stays in
 * wire_prompts_and_persistence.
 *
 * @param h Engine handle (config tiers mutated in place).
 * @param data_dir Bundled data directory (identity file resolution).
 * @internal
 * @version 2.7.3
 */
static void thread_frontmatter_samplers(
    entropic_handle_t h,
    const std::filesystem::path& data_dir) {
    for (auto& [name, tier] : h->config.models.tiers) {
        std::filesystem::path id_path;
        if (tier.identity.has_value()) {
            id_path = tier.identity.value();
        } else if (!tier.identity_disabled) {
            id_path = data_dir / "prompts" / ("identity_" + name + ".md");
        }
        if (id_path.empty() || !std::filesystem::exists(id_path)) {
            continue;
        }
        entropic::prompts::ParsedIdentity id;
        if (entropic::prompts::load_identity(id_path, id).empty()) {
            thread_frontmatter_sampler(tier, id.frontmatter);
        }
    }
}

/**
 * @brief Wire the ToolExecutor and attach it to the engine.
 * @param h Engine handle with engine + server_manager constructed.
 * @internal
 * @version 2.0.3
 */
/**
 * @brief C-safe accessor for ToolExecutor's history (P1-11).
 *
 * Extracted to satisfy the 3-return complexity gate.
 *
 * @param count Max entries to serialize.
 * @param ud ToolExecutor pointer.
 * @return malloc'd JSON string, or nullptr when empty/unset.
 * @utility
 * @version 2.0.6-rc16
 */
static char* tool_history_json_thunk(size_t count, void* ud) {
    auto* exec = static_cast<entropic::ToolExecutor*>(ud);
    if (exec == nullptr) { return nullptr; }
    auto s = exec->tool_history().to_json(count);
    if (s.empty() || s == "[]") { return nullptr; }
    auto* out = static_cast<char*>(std::malloc(s.size() + 1));
    if (out != nullptr) {
        std::memcpy(out, s.data(), s.size());
        out[s.size()] = '\0';
    }
    return out;
}

/**
 * @brief Wire the ToolExecutor and attach it to the engine.
 *
 * Constructs the ToolExecutor from existing subsystems, builds the
 * ToolExecutionInterface bridge (process_tool_calls + history_json
 * thunk), and registers it with the AgentEngine.
 *
 * @param h Engine handle with engine + server_manager constructed.
 * @internal
 * @version 2.0.6-rc16
 */
static void wire_tool_executor(entropic_handle_t h) {
    h->tool_executor = std::make_unique<entropic::ToolExecutor>(
        *h->server_manager,
        h->engine->loop_config(),
        h->engine->callbacks(),
        h->engine->build_directive_hooks());
    entropic::ToolExecutionInterface tei;
    tei.process_tool_calls = [](entropic::LoopContext& ctx,
        const std::vector<entropic::ToolCall>& calls,
        void* ud) -> std::vector<entropic::Message> {
        return static_cast<entropic::ToolExecutor*>(ud)
            ->process_tool_calls(ctx, calls);
    };
    tei.user_data = h->tool_executor.get();
    tei.history_json = tool_history_json_thunk;  // P1-11
    tei.free_fn = [](char* p) { std::free(p); };
    h->engine->set_tool_executor(tei);
}

/**
 * @brief Return the validator's last verdict as JSON for ON_COMPLETE.
 *
 * Shape: {ran, verdict, violations[], revisions_applied}. Verdict
 * is a string from {passed, revised, rejected_reverted_length,
 * rejected_max_revisions}. Returns malloc'd buffer; engine frees.
 * (E3, 2.0.6-rc17)
 *
 * @param ud entropic_engine handle.
 * @return JSON string or NULL if validator not configured.
 * @callback
 * @version 2.1.5
 */
static char* sp_get_validation(void* ud) {
    auto* h = static_cast<entropic_engine*>(ud);
    if (h == nullptr || h->validator == nullptr) { return nullptr; }
    auto r = h->validator->last_result();
    nlohmann::json v;
    v["ran"] = true;
    switch (r.verdict) {
    case entropic::ValidationVerdict::passed:
        v["verdict"] = "passed"; break;
    case entropic::ValidationVerdict::revised:
        v["verdict"] = "revised"; break;
    case entropic::ValidationVerdict::rejected_reverted_length:
        v["verdict"] = "rejected_reverted_length"; break;
    case entropic::ValidationVerdict::rejected_max_revisions:
        v["verdict"] = "rejected_max_revisions"; break;
    case entropic::ValidationVerdict::skipped:
        v["verdict"] = "skipped"; break;
    case entropic::ValidationVerdict::paused_pending_consumer:
        v["verdict"] = "paused_pending_consumer"; break;
    case entropic::ValidationVerdict::passed_consumer_override:
        v["verdict"] = "passed_consumer_override"; break;
    }
    v["revisions_applied"] = r.revision_count;
    // gh#30 (v2.1.5): structured fields the consumer needs to render
    // a "retry / override / re-prompt" UI without parsing free-form
    // reason strings.
    v["attempt_n"] = r.attempt_n;
    nlohmann::json violations = nlohmann::json::array();
    for (const auto& vi : r.final_critique.violations) {
        violations.push_back({
            {"rule", vi.rule},
            {"rule_id", vi.rule},        // alias for gh#30 schema
            {"rule_text", vi.rule},      // alias for gh#30 schema
            {"excerpt", vi.excerpt},
            {"quote", vi.excerpt},       // alias matching gh#30 "evidence.quote"
            {"explanation", vi.explanation},
            {"severity", "error"},       // gh#30: hard rejection only today
        });
    }
    v["violations"] = violations;
    return strdup(v.dump().c_str());
}

/**
 * @brief Wire hook dispatch and attach the constitutional validator.
 *
 * Bridges the handle's HookRegistry to the engine's HookInterface
 * (function-pointer indirection required by the .so boundary). If
 * constitutional validation is enabled and constitution text was
 * loaded, constructs and attaches the validator as a POST_GENERATE
 * hook.
 *
 * @param h Engine handle with engine constructed.
 * @param iface Inference interface (passed to validator for critique generation).
 * @param constitution_text Constitution text (may be empty).
 * @internal
 * @version 2.0.6-rc19
 */
static void wire_hooks_and_validator(
    entropic_handle_t h,
    entropic::InferenceInterface& iface,
    const std::string& constitution_text) {
    entropic::HookInterface hook_iface;
    hook_iface.registry = &h->hook_registry;
    hook_iface.fire_pre = [](void* reg, entropic_hook_point_t pt,
        const char* json, char** out) -> int {
        return static_cast<entropic::HookRegistry*>(reg)
            ->fire_pre(pt, json, out);
    };
    hook_iface.fire_post = [](void* reg, entropic_hook_point_t pt,
        const char* json, char** out) {
        static_cast<entropic::HookRegistry*>(reg)
            ->fire_post(pt, json, out);
    };
    hook_iface.fire_info = [](void* reg, entropic_hook_point_t pt,
        const char* json) {
        static_cast<entropic::HookRegistry*>(reg)->fire_info(pt, json);
    };
    h->engine->set_hooks(hook_iface);
    // E9 (2.0.6-rc19): forward the same hook dispatch to the tool
    // executor so PRE_TOOL_CALL / POST_TOOL_CALL actually fire.
    // Prior wiring only touched the engine; tool_executor_ held a
    // null HookInterface and silently skipped all tool hooks.
    if (h->tool_executor) {
        h->tool_executor->set_hooks(hook_iface);
    }

    if (h->config.constitutional_validation.enabled
        && !constitution_text.empty()) {
        h->validator = std::make_unique<entropic::ConstitutionalValidator>(
            h->config.constitutional_validation, constitution_text);
        h->validator->attach(&hook_iface, &iface);
        // E3 (2.0.6-rc17): expose validator verdict via ON_COMPLETE
        // hook context.
        h->engine->set_validation_provider(sp_get_validation, h);
        s_log->info("Constitutional validator attached (max_revisions={})",
                     h->config.constitutional_validation.max_revisions);
    }
}

