/**
 * @brief Wire state provider to the EntropicServer.
 *
 * v2.2.4 (gh#57): registers the additional `get_residency` callback so
 * the engine's introspection surface reflects the current VRAM
 * residency set alongside config/identities/tools/history/metrics.
 *
 * @param h Engine handle with all subsystems constructed.
 * @internal
 * @version 2.2.4
 */
static void wire_state_provider(entropic_handle_t h) {
    if (!h->server_manager) { return; }
    auto* es = dynamic_cast<entropic::EntropicServer*>(
        h->server_manager->get_server("entropic"));
    if (es == nullptr) { return; }

    entropic_state_provider_t sp{};
    sp.get_config = sp_get_config;
    sp.get_identities = sp_get_identities;
    sp.get_tools = sp_get_tools;
    sp.get_history = sp_get_history;
    sp.get_state = sp_get_state;
    sp.get_metrics = sp_get_metrics;
    sp.get_docs = sp_get_docs;
    // gh#32 (v2.1.6): storage-backed delegation recall + resume.
    sp.search_delegations = sp_search_delegations;
    sp.load_delegation_conversation = sp_load_delegation_conversation;
    // gh#57 (v2.2.4): VRAM residency-set snapshot.
    sp.get_residency = sp_get_residency;
    sp.user_data = h;
    es->set_state_provider(sp);
    s_log->info("State provider wired to entropic server");
}

/**
 * @brief Pass per-identity validation rules to the validator.
 * @param h Engine handle with validator + tier_validation_rules populated.
 * @internal
 * @version 2.0.6
 */
static void wire_tier_validation_rules(entropic_handle_t h) {
    if (!h->validator) { return; }
    for (const auto& [name, rules] : h->tier_validation_rules) {
        h->validator->set_tier_rules(name, rules);
    }
}

/**
 * @brief Build LoopConfig from parsed config.
 * @param h Engine handle with config populated.
 * @return Populated LoopConfig.
 * @utility
 * @version 2.9.6
 */
static entropic::LoopConfig build_loop_config(entropic_handle_t h) {
    entropic::LoopConfig lc;
    // gh#110 (v2.9.6): was hardcoded true, making the agent loop always
    // stream and therefore permanently out of MTP's envelope (MTP
    // rejects a bound on_token callback — see mtp_envelope.h).
    lc.stream_output = h->config.generation.stream_output;
    lc.speculative_enabled = h->config.inference.speculative.enabled;
    lc.auto_approve_tools = h->config.permissions.auto_approve;
    auto it = h->config.models.tiers.find(h->config.models.default_tier);
    if (it != h->config.models.tiers.end()) {
        lc.context_length = it->second.context_length;
    }
    // gh#80 (v2.5.0): map the generation.budget_mode string to the
    // BudgetMode enum. Unknown values resolve to off with a warning.
    const std::string& bm = h->config.generation.budget_mode;
    if (bm == "tokens") {
        lc.budget_mode = entropic::BudgetMode::tokens;
    } else if (bm == "wall_clock") {
        lc.budget_mode = entropic::BudgetMode::wall_clock;
    } else {
        if (bm != "off") {
            s_log->warn("Unknown generation.budget_mode '{}' — "
                        "treating as 'off'", bm);
        }
        lc.budget_mode = entropic::BudgetMode::off;
    }
    lc.budget_limit = h->config.generation.budget_limit;
    // A non-positive limit can't gate anything — disable to avoid a
    // pathological "exhausted at zero" loop.
    if (lc.budget_limit <= 0) {
        lc.budget_mode = entropic::BudgetMode::off;
    }
    return lc;
}

/**
 * @brief Start the external MCP bridge if enabled in config.
 *
 * Creates an ExternalBridge listening on a unix domain socket so
 * external MCP clients (Claude Code, etc.) can talk to the running
 * engine without spawning a separate process.
 *
 * @param h Engine handle (must be fully configured).
 * @internal
 * @version 2.0.8
 */
static void start_external_bridge(entropic_handle_t h) {
    if (!h->config.mcp.external.enabled) { return; }
    auto project_dir = h->config.config_dir.empty()
        ? std::filesystem::current_path()
        : h->config.config_dir;
    h->external_bridge = std::make_unique<entropic::ExternalBridge>(
        h, h->config.mcp.external, project_dir);
    if (!h->external_bridge->start()) {
        s_log->warn("External MCP bridge failed to start");
        h->external_bridge.reset();
    }
}

/**
 * @brief Post-parse config setup: subsystem construction + wiring.
 *
 * v2.1.10 (gh#40 + fallout): observer rewiring at engine construction
 * is bundled into `rewire_observers` so pre-configure stream, queue,
 * and state observers all survive engine construction AND the
 * EngineCallbacks shuffle that run_streaming performs.
 *
 * @param h Engine handle with config populated.
 * @return ENTROPIC_OK or error code.
 * @internal
 * @version 2.1.10.1
 */
/**
 * @brief Refuse a second configure on the same handle (gh#58).
 *
 * Re-configure would leak raw pointers captured during the first
 * pass into subsystems that already wired against the original
 * orchestrator/engine/mcp_auth.
 *
 * @internal
 * @version 2.2.5
 */
static entropic_error_t reject_if_configured(entropic_handle_t h) {
    if (!h->configured.load()) { return ENTROPIC_OK; }
    h->last_error = "handle already configured";
    s_log->error("{}", h->last_error);
    return ENTROPIC_ERROR_INVALID_STATE;
}

/**
 * @brief Shared body of all entropic_configure* entry points.
 * @internal
 * @version 2.2.6
 */
/**
 * @brief Construct the orchestrator + grammar fallback for a handle.
 *
 * Extracted from `configure_common` in v2.2.9 to keep SLOC under the
 * knots gate after v2.2.6's per-handle InterfaceContext wiring grew
 * the body past 50 lines.
 *
 * @internal
 * @version 2.2.9
 */
static entropic_error_t init_orchestrator(
    entropic_handle_t h, const std::filesystem::path& data_dir) {
    h->orchestrator = std::make_unique<entropic::ModelOrchestrator>();
    if (!h->orchestrator->initialize(h->config)) {
        h->last_error = "orchestrator initialization failed";
        s_log->error("{}", h->last_error);
        return ENTROPIC_ERROR_LOAD_FAILED;
    }
    // Fallback grammar loading: only if initialize() didn't find
    // grammars via config_dir. Avoids overwriting patched grammars.
    if (h->orchestrator->grammar_registry().size() == 0) {
        h->orchestrator->load_grammars_from(data_dir / "grammars");
    }
    return ENTROPIC_OK;
}

/**
 * @brief Build the engine + inference interfaces (configure step 2).
 *
 * Extracted from configure_common to keep it knots-clean. Creates the
 * MCP-auth + identity managers, the per-handle orchestrator interface
 * (gh#58), the AgentEngine, and rewires observers/interrupt/tools.
 *
 * @param h Engine handle.
 * @param data_dir Resolved data directory.
 * @internal
 * @version 2.3.8
 */
static void init_engine_and_interfaces(
    entropic_handle_t h, const std::filesystem::path& data_dir) {
    h->mcp_auth = std::make_unique<entropic::MCPAuthorizationManager>();
    h->identity_manager = std::make_unique<entropic::IdentityManager>(
        entropic::IdentityManagerConfig{});
    // P1-7: route identity changes to prompt-cache invalidation.
    h->identity_manager->set_cache_invalidator(
        [](void* ud) {
            auto* orch = static_cast<entropic::ModelOrchestrator*>(ud);
            if (orch) { orch->clear_all_prompt_caches(); }
        }, h->orchestrator.get());
    init_mcp_servers(h, data_dir);

    // gh#58 follow-up (v2.2.6): per-handle InterfaceContext. Pre-v2.2.6
    // build_orchestrator_interface stored the context in a process-
    // global static, so a second configure freed the first handle's
    // context and h1.run() segfaulted on a use-after-free.
    h->inference_iface = entropic::build_orchestrator_interface(
        h->orchestrator.get(), h->config.models.default_tier,
        &h->inference_iface_ctx);
    h->inference_iface.get_tool_prompt = facade_get_tool_prompt;
    h->inference_iface.tool_prompt_data = h;
    auto lc = build_loop_config(h);
    h->engine = std::make_unique<entropic::AgentEngine>(
        h->inference_iface, lc, h->config.compaction);
    // gh#76 (v2.3.27): wire the compactor registry now that the engine
    // owns the CompactionManager that backs the default-compactor
    // fallback. Pre-v2.3.27 the field was declared but never
    // constructed, so every `entropic_register_compactor` /
    // `entropic_compact` call returned INVALID_STATE.
    h->compactor_registry =
        std::make_unique<entropic::CompactorRegistry>(
            h->engine->compaction_manager());
    rewire_observers(h);  // gh#40 + fallout (v2.1.10)
    wire_external_interrupt(h);  // P1-10
    wire_tool_executor(h);
}

/**
 * @brief Assemble prompts + wire validation/persistence (config step 3).
 *
 * Extracted from configure_common to keep it knots-clean.
 *
 * @param h Engine handle.
 * @param data_dir Resolved data directory.
 * @internal
 * @version 2.9.19
 */
static void wire_prompts_and_persistence(
    entropic_handle_t h, const std::filesystem::path& data_dir) {
    auto shared_prefix = build_shared_prompt_prefix(h, data_dir);
    cache_tier_allowed_tools(h, data_dir);       // gh#121: must fill h->tier_allowed_tools
    populate_tier_info(h, data_dir, shared_prefix);  // before populate reads it
    h->engine->set_handoff_rules(h->config.routing.handoff_rules);

    wire_hooks_and_validator(h, h->inference_iface, shared_prefix);
    wire_tier_validation_rules(h);

    init_persistence(h);
    wire_state_provider(h);

    h->engine->set_system_prompt(
        entropic::prompts::assemble(h->config, data_dir));
    if (h->session_logger) {
        h->engine->set_session_logger(h->session_logger.get());
    }
}

/**
 * @brief Shared body of all entropic_configure* entry points.
 * @internal
 * @version 2.7.3
 */
static entropic_error_t configure_common(entropic_handle_t h) {
    if (auto rc = reject_if_configured(h); rc != ENTROPIC_OK) { return rc; }
    // gh#59 follow-up (v2.3.7): honor console_logging before any init
    // logging fires. When false, strip the stderr console sink so the
    // file sink (already installed by setup_session) is the only route
    // — TUI consumers paint to fd 2 and can't tolerate engine output
    // there. Default (true) is a no-op; operators keep stderr logs.
    entropic::log::set_console_enabled(h->config.console_logging);
    auto data_dir = entropic::config::resolve_data_dir(h->config);
    // gh#94 (v2.7.3): thread per-tier frontmatter samplers into the config
    // BEFORE the orchestrator snapshots it by value. The engine-bound
    // frontmatter wiring stays in wire_prompts_and_persistence (post-engine).
    thread_frontmatter_samplers(h, data_dir);
    if (auto rc = init_orchestrator(h, data_dir); rc != ENTROPIC_OK) {
        return rc;
    }

    init_engine_and_interfaces(h, data_dir);
    wire_prompts_and_persistence(h, data_dir);

    h->configured.store(true);
    start_external_bridge(h);
    s_log->info("configure complete");
    return ENTROPIC_OK;
}

/**
 * @brief entropic_configure body — wrapped by `c_api_try` in the public entry.
 * @internal
 * @version 2.9.5
 */
static entropic_error_t do_configure_json(
    entropic_handle_t handle, const char* config_json) {
    handle->bundled_models.auto_discover_and_load();
    auto err = entropic::config::load_config_from_string(
        config_json, handle->bundled_models, handle->config);
    if (!err.empty()) {
        handle->last_error = err;
        s_log->error("configure: {}", err);
        return ENTROPIC_ERROR_INVALID_CONFIG;
    }
    // gh#109 follow-up: parity with configure_dir/configure_from_file.
    // Without this, a JSON-string config that sets "log_dir" got no
    // session.log at all — config.log_dir was honored for the sqlite/
    // conversation store (init_persistence) but never wired to the
    // per-handle log dispatcher, so no file sink existed for any
    // HandleLogScope-tagged log line to route to.
    if (!handle->config.log_dir.empty()) {
        entropic::log::setup_session(handle->config.log_dir);
        entropic::log::register_handle_log(
            handle->log_id, handle->config.log_dir);
    }
    return configure_common(handle);
}

/**
 * @brief Configure the engine from a JSON/YAML config string.
 *
 * @return ENTROPIC_OK on success.
 * @internal
 * @version 2.0.2
 */
entropic_error_t entropic_configure(
    entropic_handle_t handle,
    const char* config_json) {
    if (!handle || !config_json) {
        return !handle ? ENTROPIC_ERROR_INVALID_HANDLE
                       : ENTROPIC_ERROR_INVALID_ARGUMENT;
    }
    entropic::HandleApiLock lock(handle);  // gh#59 v2.3.1: mutex + log scope
    return c_api_try(handle,
        [&]() { return do_configure_json(handle, config_json); });
}

/**
 * @brief entropic_configure_from_file body — wrapped by `c_api_try`.
 * @internal
 * @version 2.3.13
 */
static entropic_error_t do_configure_from_file(
    entropic_handle_t handle, const char* config_path) {
    handle->bundled_models.auto_discover_and_load();
    auto err = entropic::config::load_config_from_file(
        config_path, handle->bundled_models, handle->config);
    if (!err.empty()) {
        handle->last_error = err;
        s_log->error("configure_from_file: {}", err);
        return ENTROPIC_ERROR_INVALID_CONFIG;
    }
    // Parity with configure_dir: if the parsed config specifies a
    // log_dir, start session logging there. Without this, consumers
    // using the file-based API get no session.log on disk even when
    // their YAML declares log_dir.
    if (!handle->config.log_dir.empty()) {
        entropic::log::setup_session(handle->config.log_dir);
        // gh#59 (v2.3.1): per-handle dispatcher file sink so log lines
        // emitted within this handle's HandleLogScope route to this
        // handle's session.log only.
        entropic::log::register_handle_log(
            handle->log_id, handle->config.log_dir);
    }
    return configure_common(handle);
}

/**
 * @brief Configure the engine from a YAML config file.
